"""Checkpointed LSTM Baseline v1.1 with 60-day inner temporal early stopping."""
from __future__ import annotations
import hashlib,json,zipfile
from pathlib import Path
import numpy as np,pandas as pd,torch
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
from .data import build_system_sequences
from .evaluate import metric_rows,grouped,daily_losses
from .train_v1_1 import fit_early_stopping,fit_fixed_epochs

def sha(path):
    h=hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda:stream.read(1048576),b""): h.update(block)
    return h.hexdigest()
def load_config(root): return json.loads((root/"config/lstm_baseline_v1_1.yaml").read_text(encoding="utf-8"))
def subset(data,indices): return {k:(v[indices] if isinstance(v,np.ndarray) else [v[i] for i in indices]) for k,v in data.items() if k!="meta"}|{"meta":[data["meta"][i] for i in indices]}
def prediction_rows(data,prediction):
    output=[]
    for i,meta in enumerate(data["meta"]):
        for j,horizon in enumerate(meta["horizons"]):
            output.append({"system_id":meta["system_id"],"site_id":meta["site_id"],"target_date_local":pd.Timestamp(meta["target_date_local"]).strftime("%Y-%m-%d"),"issue_time_utc":meta["issue_time_utc"],"horizon":int(horizon),"target_timestamp_utc":meta["target_timestamp_utc"][j],"target_pu":data["targets"][i,j],"target_valid":bool(meta["target_valid"][j]),"is_daylight":bool(meta["is_daylight"][j]),"persistence_pu":meta["persistence_pu"][j],"persistence_valid":bool(meta["persistence_valid"][j]),"eval_mask":bool(meta["eval_mask"][j]),"split":meta["split"],"lstm_pu":prediction[i,j]})
    return pd.DataFrame(output)
def _history_frame(history,stage,system,candidate,fold,best_epoch):
    result=pd.DataFrame(history); result.insert(0,"stage",stage); result.insert(1,"system_id",system); result.insert(2,"candidate_id",candidate); result.insert(3,"fold",fold); result["best_epoch"]=best_epoch; return result
def _candidate_map(cfg): return {item["id"]:item for item in cfg["candidates"]}
def _base_metrics(test,column,prefix):
    values=[]
    for system,frame in test.groupby("system_id",sort=True):
        row=metric_rows(frame,column); values.append({"system_id":system,f"{prefix}_RMSE_pu":row["RMSE_pu"],f"{prefix}_nRMSE_percent":row["nRMSE_percent"]})
    return pd.DataFrame(values)
def _figures(root,system,site,horizon):
    folder=root/"figures/lstm_v1_1"; folder.mkdir(parents=True,exist_ok=True); paths=[]
    x=np.arange(len(system)); fig,ax=plt.subplots(figsize=(12,5))
    for offset,column,label in [(-.3,"persistence_nRMSE_percent","Persistence"),(-.1,"sarima_nRMSE_percent","SARIMA"),(.1,"rf_nRMSE_percent","RF"),(.3,"nRMSE_percent","LSTM v1.1")]: ax.bar(x+offset,system[column],.2,label=label)
    ax.set_xticks(x,system.system_id,rotation=55,ha="right"); ax.set_ylabel("nRMSE (%)"); ax.legend(frameon=False); fig.tight_layout(); path=folder/"benchmark_nrmse_by_system.svg"; fig.savefig(path); plt.close(fig); paths.append(path)
    fig,ax=plt.subplots(figsize=(9,4)); ax.plot(horizon.horizon,horizon.nRMSE_percent,marker="o"); ax.set_xlabel("Target local hour"); ax.set_ylabel("LSTM v1.1 nRMSE (%)"); fig.tight_layout(); path=folder/"error_by_horizon.svg"; fig.savefig(path); plt.close(fig); paths.append(path)
    fig,ax=plt.subplots(figsize=(8,5)); ax.barh(site.site_id,site.skill_RMSE_vs_rf); ax.axvline(0,color="black"); ax.set_xlabel("RMSE skill vs RF"); fig.tight_layout(); path=folder/"skill_vs_rf_by_site.svg"; fig.savefig(path); plt.close(fig); paths.append(path); return paths
def run(project_root=None):
    root=Path(project_root) if project_root else Path(__file__).resolve().parents[3]; cfg=load_config(root); out=root/"outputs/lstm_v1_1"; checkpoints=out/"_checkpoints"; finals=out/"_final_checkpoints"; checkpoints.mkdir(parents=True,exist_ok=True); finals.mkdir(parents=True,exist_ok=True)
    assert sha(root/cfg["frozen_split_manifest"])==cfg["frozen_split_manifest_sha256"]; assert sha(root/cfg["frozen_windows"])==cfg["frozen_windows_sha256"]; assert sha(root/cfg["canonical_input"])==cfg["canonical_input_sha256"]
    split=pd.read_csv(root/cfg["frozen_split_manifest"]); systems=sorted(split.system_id.unique()); datasets={system:build_system_sequences(root,system,cfg) for system in systems}; cv_diagnostics=[]
    for system in systems:
        data=datasets[system]; dates=pd.DatetimeIndex(pd.to_datetime([meta["target_date_local"] for meta in data["meta"]])); folds=split[(split.system_id==system)&(split.partition=="cross_validation")].sort_values("fold")
        for candidate in cfg["candidates"]:
            for _,foldrow in folds.iterrows():
                fold=int(foldrow.fold); stem=f"{system}__{candidate['id']}__fold{fold}"; json_path=checkpoints/f"{stem}.json"; prediction_path=checkpoints/f"{stem}.parquet"; history_path=checkpoints/f"{stem}_history.csv"
                if json_path.exists() and prediction_path.exists() and history_path.exists(): cv_diagnostics.append(json.loads(json_path.read_text(encoding="utf-8"))); continue
